/** Pending suggestions from employees. Some deliberately duplicate existing items to demo "Merge into existing". */
export function demoPendingItems(categoryIdByName: Map<string, string>): Item[] {
  const at = '2026-11-03T10:00:00.000Z'
  const office = categoryIdByName.get('Office Supplies')!
  const kitchen = categoryIdByName.get('Kitchen Supplies')!
  const cleaning = categoryIdByName.get('Cleaning & Hygiene Supplies')!
  return [
    { id: 'itm_p1', category_id: office, name: 'Bottled water', status: 'pending', usage_count: 0, suggested_by: 'usr_efua', created_at: at },
    { id: 'itm_p2', category_id: kitchen, name: 'Tea bags', status: 'pending', usage_count: 0, suggested_by: 'usr_kofi', created_at: at },
    { id: 'itm_p3', category_id: office, name: 'Whiteboard markers', status: 'pending', usage_count: 0, suggested_by: 'usr_akosua', created_at: at },
    { id: 'itm_p4', category_id: cleaning, name: 'Scouring pads', status: 'pending', usage_count: 0, suggested_by: 'usr_yaw', created_at: at },
  ]
}

